import{_ as i,c as t,o as a,ag as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Politique de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md","lastUpdated":1794112334000}'),s={name:"fr/guide/privacy.md"};function o(r,e,l,u,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to &quot;Politique de confidentialité&quot;">​</a></h1><h2 id="collecte-de-donnees" tabindex="-1">Collecte de données <a class="header-anchor" href="#collecte-de-donnees" aria-label="Permalink to &quot;Collecte de données&quot;">​</a></h2><p>Le développeur ne collecte aucune donnée via cette application.</p><h3 id="informations-que-nous-ne-collectons-pas" tabindex="-1">Informations que nous ne collectons pas <a class="header-anchor" href="#informations-que-nous-ne-collectons-pas" aria-label="Permalink to &quot;Informations que nous ne collectons pas&quot;">​</a></h3><ul><li>Informations personnelles</li><li>Statistiques d&#39;utilisation</li><li>Informations sur l&#39;appareil</li><li>Données de localisation</li><li>Contenu ou métadonnées des images</li><li>Historique de navigation</li><li>Toute autre donnée utilisateur</li></ul><h3 id="extension-chrome" tabindex="-1">Extension Chrome <a class="header-anchor" href="#extension-chrome" aria-label="Permalink to &quot;Extension Chrome&quot;">​</a></h3><p>L&#39;extension Chrome de Nicasa demande l&#39;accès au contenu des pages uniquement pour extraire les URL des images dans le cadre de la fonction de visualisation. L&#39;extension :</p><ul><li>ne lit ni ne stocke l&#39;historique de navigation</li><li>ne suit pas le comportement des utilisateurs</li><li>ne transmet aucune donnée à des serveurs externes</li><li>traite uniquement les URL d&#39;images localement dans votre navigateur</li></ul><h3 id="traitement-local" tabindex="-1">Traitement local <a class="header-anchor" href="#traitement-local" aria-label="Permalink to &quot;Traitement local&quot;">​</a></h3><p>Tout le traitement, l&#39;édition et la visualisation des images se font localement sur votre appareil. Aucune image ni donnée n&#39;est envoyée à des serveurs externes.</p><h3 id="autorisations" tabindex="-1">Autorisations <a class="header-anchor" href="#autorisations" aria-label="Permalink to &quot;Autorisations&quot;">​</a></h3><p>Nicasa demande les autorisations suivantes sous macOS :</p><ul><li><strong>Enregistrement de l&#39;écran</strong> : nécessaire pour la fonction de capture</li><li><strong>Accessibilité</strong> : facultatif, utilisé pour les fonctions du mode superposition</li><li><strong>Fichiers et dossiers</strong> : accès aux répertoires choisis par l&#39;utilisateur pour parcourir les images</li></ul><p>Ces autorisations peuvent être gérées dans Réglages Système &gt; Confidentialité et sécurité.</p><h3 id="services-tiers" tabindex="-1">Services tiers <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers&quot;">​</a></h3><p>Nicasa n&#39;intègre aucun service tiers d&#39;analyse, de publicité ou de collecte de données.</p><h3 id="options-de-confidentialite" tabindex="-1">Options de confidentialité <a class="header-anchor" href="#options-de-confidentialite" aria-label="Permalink to &quot;Options de confidentialité&quot;">​</a></h3><p>Si vous souhaitez exercer vos droits en matière de confidentialité (par exemple : demandes d&#39;accès, de suppression, de portabilité ou d&#39;opposition), ou si vous pensez que Nicasa détient des données personnelles vous concernant, vous pouvez soumettre une demande par l&#39;un des moyens suivants :</p><ul><li>E-mail : <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Ouvrir un ticket de confidentialité : <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>Utiliser notre page Options de confidentialité : /fr/guide/privacy-choices</li></ul><p>Étant donné que Nicasa ne collecte pas de données personnelles comme décrit ci-dessus, de nombreuses demandes recevront une confirmation qu&#39;aucune donnée personnelle n&#39;est détenue. Si nous commençons à collecter des données personnelles dans de futures versions, cette page et le formulaire Options de confidentialité permettront de soumettre et de suivre les demandes.</p><p>Nous nous efforçons de répondre aux demandes légitimes dans un délai de 30 jours.</p><h3 id="mises-a-jour" tabindex="-1">Mises à jour <a class="header-anchor" href="#mises-a-jour" aria-label="Permalink to &quot;Mises à jour&quot;">​</a></h3><p>Cette politique de confidentialité peut être mise à jour avec les nouvelles versions de l&#39;application. Les utilisateurs seront informés de tout changement important.</p><h3 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h3><p>Pour toute question relative à la confidentialité, contactez-nous via le <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">dépôt GitHub</a>.</p>',25)])])}const h=i(s,[["render",o]]);export{m as __pageData,h as default};
